class Solution {
public:
    int countGoodSubstrings(string s) {
        int count = 0;
        for (int i = 0; i + 2 < (int)s.size(); ++i) {
            unordered_set<char> seen(s.begin() + i, s.begin() + i + 3);
            if (seen.size() == 3) ++count;
        }
        return count;
    }
};

