class Solution {
    public int countGoodSubstrings(String s) {
        int count = 0;
        for (int i = 0; i + 2 < s.length(); i++) {
            Set<Character> seen = new HashSet<>();
            for (int j = i; j < i + 3; j++) seen.add(s.charAt(j));
            if (seen.size() == 3) count++;
        }
        return count;
    }
}

